window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c88666f7cf08b202"]={"versions": [{"id": "FIG-c88666f7cf08b202", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Aktivitätsdiagramm (UML Activity Diagram) zur Spezifikation eines algorithmischen Kontrollflusses.\n</li><li><strong>Architektur-Kontext:</strong>\n<ul class=\"fig-list\"><li>Komponente der AUTOSAR E2E-Library (<code>E2E</code>), angesiedelt in den AUTOSAR Foundation / Classic Platform Services bzw. Adaptive Platform Functional Clusters (<code>ara::com</code> / E2E-Protection).\n</li><li>Spezifiziert den Teilschritt „Read SourceID“ innerhalb der Empfänger-Prüffunktion <code>E2E_PXXmSinkCheck()</code>.\n</li><li><code>XX</code> fungiert als Platzhalter für methodenspezifische E2E-Profile (z. B. Profile 04m, 07m, 22m) zur Absicherung von Client/Server- und RPC-Kommunikationsmustern (Method Communication, typisch im Kontext von SOME/IP und Service-orientierten Architekturen).\n</li><li>Funktionaler Zweck: Extrahieren der Quellkennung (<code>SourceID</code> / <code>MessageID</code>) aus dem empfangenen Rohdaten-Bytestream (<code>Data</code>), um nachfolgend Mehrfachsender bzw. Client-Instanzen in 1:n-Kommunikationsbeziehungen fehlerfrei zu identifizieren und zu validieren.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivität / Funktionskontext:</strong>\n<ul class=\"fig-list\"><li><code>E2E_PXXmSinkCheck()</code>: E2E-Prüfroutine auf Senken-/Empfängerseite (Method Sink).\n</li></ul>\n</li><li><strong>Datenstrukturen &amp; Variablen:</strong>\n<ul class=\"fig-list\"><li><code>Data</code>: Eingehender Bytestring / Serialisierte Payload inklusive E2E-Header (<code>uint8*</code>).\n</li><li><code>ReceivedSourceID</code>: Lokale Variable (Typ <code>uint32</code>), die den extrahierten Identifikator aufnimmt.\n</li><li><code>Offset</code>: Konfigurierter Basis-Byte-Offset des E2E-Headers innerhalb der PDU/Payload (<code>Config-&gt;Offset</code>).\n</li><li><code>PXXMESSAGE_POS</code>: Profilspezifische relative Byte-Position des <code>MessageID</code>-Feldes im E2E-Header.\n</li></ul>\n</li><li><strong>Stereotypen &amp; Spezifikationsanker:</strong>\n<ul class=\"fig-list\"><li>Anforderung <code>[PRS_E2E_01197]</code>, abgeleitet aus <code>[RS_E2E_08539]</code>.\n</li><li>Stereotyp-Klassifikation: Normativer Verhaltensstandard für profilbasierte Algorithmen (Method Profile Template).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initial Node:</strong> Eintritt in den Sub-Ablauf „Read SourceID“ innerhalb von <code>E2E_PXXmSinkCheck()</code>.\n</li><li><strong>Aktion „Copy MessageID“:</strong>\n<ul class=\"fig-list\"><li><strong>Quellbereich:</strong> 4 aufeinanderfolgende Bytes im PDU-Array von <code>Offset + PXXMESSAGE_POS</code> bis <code>Offset + PXXMESSAGE_POS + 3</code>.\n</li><li><strong>Bitbreite &amp; Maskierung:</strong> <code>MessageID</code> umfasst exakt 28 Bits. Es werden die 28 niederwertigsten Bits (least significant bits) extrahiert; die oberen 4 Bits des 32-Bit-Wortes werden ignoriert bzw. ausmaskiert.\n</li><li><strong>Bytereihenfolge:</strong> Serialisierung im Bytestream liegt in <strong>Big-Endian</strong>-Order (Network Byte Order) vor und wird entsprechend endianness-konform in die lokale 32-Bit-Variable <code>ReceivedSourceID</code> überführt.\n</li></ul>\n</li><li><strong>Activity Final Node:</strong> Terminierung des Extraktionsschritts; Übergabe von <code>ReceivedSourceID</code> an den nachgelagerten Prüfschritt (Vergleich gegen erwartete Quell-IDs).\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Byte- und Bit-Handling (Bit-Packing):</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen sicherstellen, dass bei der 28-Bit-Extraktion über eine 4-Byte-Grenze keine Host-Endianness-Fehler auftreten. Auf Little-Endian-Mikrocontrollern (z. B. ARM Cortex-R/M, TriCore) ist zwingend ein Byte-Swap (<code>REV</code>/<code>__builtin_bswap32</code>) bzw. schiebe- und maskierungsbasierte Rekonstruktion (<code>uint32</code>) anzuwenden.\n</li><li>Bitmaske: <code>ReceivedSourceID = (RawWord32BigEndian) &amp; 0x0FFFFFFFu</code>.\n</li></ul>\n</li><li><strong>Speicherzugriff &amp; Alignment:</strong>\n<ul class=\"fig-list\"><li>Der Offset <code>Offset + PXXMESSAGE_POS</code> ist im Bytestrom nicht zwingend 32-Bit-aligned. Ein direkter Cast auf <code>uint32*</code> führt auf Architekturen mit Alignment-Faults (z. B. ältere ARM-Cores) zu Laufzeit-Exceptions. Die Extraktion muss daher byte-weise erfolgen.\n</li></ul>\n</li><li><strong>PDU-Längenprüfung (Precondition):</strong>\n<ul class=\"fig-list\"><li>Vor Ausführung dieses Schritts muss die PDU-Länge gegen <code>Offset + PXXMESSAGE_POS + 4</code> validiert sein (<code>Length Check</code>), um Pufferüberläufe (Buffer Over-Read) bei korrumpierten oder zu kurzen Nachrichten zu verhindern.\n</li></ul>\n</li></ul>"}, {"id": "FIG-418d4172881a8a07", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Aktivitätsdiagramm (UML Activity Diagram) zur Spezifikation eines algorithmischen Kontrollflusses.\n</li><li><strong>Architektur-Kontext:</strong>\n<ul class=\"fig-list\"><li>Komponente der AUTOSAR E2E-Library (<code>E2E</code>), angesiedelt in den AUTOSAR Foundation / Classic Platform Services bzw. Adaptive Platform Functional Clusters (<code>ara::com</code> / E2E-Protection).\n</li><li>Spezifiziert den Teilschritt „Read SourceID“ innerhalb der Empfänger-Prüffunktion <code>E2E_PXXmSinkCheck()</code>.\n</li><li><code>XX</code> fungiert als Platzhalter für methodenspezifische E2E-Profile (z. B. Profile 04m, 07m, 22m) zur Absicherung von Client/Server- und RPC-Kommunikationsmustern (Method Communication, typisch im Kontext von SOME/IP und Service-orientierten Architekturen).\n</li><li>Funktionaler Zweck: Extrahieren der Quellkennung (<code>SourceID</code> / <code>MessageID</code>) aus dem empfangenen Rohdaten-Bytestream (<code>Data</code>), um nachfolgend Mehrfachsender bzw. Client-Instanzen in 1:n-Kommunikationsbeziehungen fehlerfrei zu identifizieren und zu validieren.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivität / Funktionskontext:</strong>\n<ul class=\"fig-list\"><li><code>E2E_PXXmSinkCheck()</code>: E2E-Prüfroutine auf Senken-/Empfängerseite (Method Sink).\n</li></ul>\n</li><li><strong>Datenstrukturen &amp; Variablen:</strong>\n<ul class=\"fig-list\"><li><code>Data</code>: Eingehender Bytestring / Serialisierte Payload inklusive E2E-Header (<code>uint8*</code>).\n</li><li><code>ReceivedSourceID</code>: Lokale Variable (Typ <code>uint32</code>), die den extrahierten Identifikator aufnimmt.\n</li><li><code>Offset</code>: Konfigurierter Basis-Byte-Offset des E2E-Headers innerhalb der PDU/Payload (<code>Config-&gt;Offset</code>).\n</li><li><code>PXXMESSAGE_POS</code>: Profilspezifische relative Byte-Position des <code>MessageID</code>-Feldes im E2E-Header.\n</li></ul>\n</li><li><strong>Stereotypen &amp; Spezifikationsanker:</strong>\n<ul class=\"fig-list\"><li>Anforderung <code>[PRS_E2E_01197]</code>, abgeleitet aus <code>[RS_E2E_08539]</code>.\n</li><li>Stereotyp-Klassifikation: Normativer Verhaltensstandard für profilbasierte Algorithmen (Method Profile Template).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initial Node:</strong> Eintritt in den Sub-Ablauf „Read SourceID“ innerhalb von <code>E2E_PXXmSinkCheck()</code>.\n</li><li><strong>Aktion „Copy MessageID“:</strong>\n<ul class=\"fig-list\"><li><strong>Quellbereich:</strong> 4 aufeinanderfolgende Bytes im PDU-Array von <code>Offset + PXXMESSAGE_POS</code> bis <code>Offset + PXXMESSAGE_POS + 3</code>.\n</li><li><strong>Bitbreite &amp; Maskierung:</strong> <code>MessageID</code> umfasst exakt 28 Bits. Es werden die 28 niederwertigsten Bits (least significant bits) extrahiert; die oberen 4 Bits des 32-Bit-Wortes werden ignoriert bzw. ausmaskiert.\n</li><li><strong>Bytereihenfolge:</strong> Serialisierung im Bytestream liegt in <strong>Big-Endian</strong>-Order (Network Byte Order) vor und wird entsprechend endianness-konform in die lokale 32-Bit-Variable <code>ReceivedSourceID</code> überführt.\n</li></ul>\n</li><li><strong>Activity Final Node:</strong> Terminierung des Extraktionsschritts; Übergabe von <code>ReceivedSourceID</code> an den nachgelagerten Prüfschritt (Vergleich gegen erwartete Quell-IDs).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Byte- und Bit-Handling (Bit-Packing):</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen sicherstellen, dass bei der 28-Bit-Extraktion über eine 4-Byte-Grenze keine Host-Endianness-Fehler auftreten. Auf Little-Endian-Mikrocontrollern (z. B. ARM Cortex-R/M, TriCore) ist zwingend ein Byte-Swap (<code>REV</code>/<code>__builtin_bswap32</code>) bzw. schiebe- und maskierungsbasierte Rekonstruktion (<code>uint32</code>) anzuwenden.\n</li><li>Bitmaske: <code>ReceivedSourceID = (RawWord32BigEndian) &amp; 0x0FFFFFFFu</code>.\n</li></ul>\n</li><li><strong>Speicherzugriff &amp; Alignment:</strong>\n<ul class=\"fig-list\"><li>Der Offset <code>Offset + PXXMESSAGE_POS</code> ist im Bytestrom nicht zwingend 32-Bit-aligned. Ein direkter Cast auf <code>uint32*</code> führt auf Architekturen mit Alignment-Faults (z. B. ältere ARM-Cores) zu Laufzeit-Exceptions. Die Extraktion muss daher byte-weise erfolgen.\n</li></ul>\n</li><li><strong>PDU-Längenprüfung (Precondition):</strong>\n<ul class=\"fig-list\"><li>Vor Ausführung dieses Schritts muss die PDU-Länge gegen <code>Offset + PXXMESSAGE_POS + 4</code> validiert sein (<code>Length Check</code>), um Pufferüberläufe (Buffer Over-Read) bei korrumpierten oder zu kurzen Nachrichten zu verhindern.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-c88666f7cf08b202", "to": "FIG-418d4172881a8a07", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
